import arrtForm from './components/relationManageComponent/arrtForm'
import { globalattrSearch, globalattrDel } from "@/api/system/relationManage";

export default {
  components: {
    arrtForm
  },
  data() {
    return{
      tableData: [],
      tableHeight: undefined,
      tableLoading: false,
      // 弹窗
      showForm: false,
      showType: '',
      arrtId: '',
    }
  },
  mounted() {
    this.setPageContentHeight()
    this.setTableHeight()
    this.getList()
  },
  methods: {
    // 设置表格高度
    setTableHeight() {
      let bodyBox = document.getElementsByClassName('page_body')
      this.tableHeight = bodyBox[0].offsetHeight + 'px'
    },
    getList() {
      this.tableLoading = true
      globalattrSearch().then(res => {
        this.tableData = res.Return
        this.tableLoading = false
      }).catch(() => {
        this.tableLoading = false
      })
    },
    // 删除
    delArrt(row) {
      this.$confirm('确定删除该全局属性?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        globalattrDel({id: row.id}).then(res => {
          this.$message({
            type: 'success',
            message: '删除成功！'
          });
          this.getList()
        })
      })
    },
    // 编辑
    editArrt(row) {
      this.showType = '修改'
      this.arrtId = row.id
      this.showForm = true
    },
    saveGlobalArrt() {
      this.showForm = false
      this.getList()
    }
  }
}
